type Constructor = new (...args: any[]) => object;
function mark<T extends Constructor>(value: T, context: ClassDecoratorContext): T {
  if (context.kind !== "class") throw new Error("kind");
  return value;
}
@mark
export class Decorated { label: string = "ready"; }

